if (velocities.size() != masses.size() || velocities.empty()) return;

const double kB = 1.38064852e-23;          // Boltzmann constant (J/K)
const double amu = 1.66053906660e-27;       // atomic mass unit (kg)

// 1. Draw Gaussian random numbers for each velocity component
std::mt19937 rng(std::random_device{}());
std::normal_distribution<double> gauss(0.0, 1.0);

for (size_t i = 0; i < velocities.size(); ++i) {
    double sigma = std::sqrt(kB * temperature / (masses[i] * amu));
    velocities[i].x = gauss(rng) * sigma;
    velocities[i].y = gauss(rng) * sigma;
    velocities[i].z = gauss(rng) * sigma;
}

// 2. Remove center-of-mass velocity
vec3 comMomentum(0, 0, 0);
double totalMass = 0.0;
for (size_t i = 0; i < velocities.size(); ++i) {
    double m = masses[i] * amu;
    comMomentum += m * velocities[i];
    totalMass += m;
}
vec3 comVelocity = comMomentum / totalMass;
for (size_t i = 0; i < velocities.size(); ++i) {
    velocities[i] -= comVelocity;
}

// 3. Rescale to exact temperature
double kinetic = 0.0;
for (size_t i = 0; i < velocities.size(); ++i) {
    kinetic += 0.5 * masses[i] * amu * velocities[i].lengthSquared();
}
double ndof = 3.0 * velocities.size() - 3;          // subtract 3 translational DOF
double currentTemp = 2.0 * kinetic / (ndof * kB);
double scale = std::sqrt(temperature / currentTemp);
for (size_t i = 0; i < velocities.size(); ++i) {
    velocities[i] *= scale;
}

